perguntas.enunciado:
Qual será a saída do código?

int a = 5;
int b = 2;

printf("%d", a / b);

Qual será a saída do código?

int x = 5;

printf("%d", x++ + ++x);

Qual será o valor final de soma?

int soma = 0;

for (int i = 1; i <= 5; i++) {
    if (i % 2 == 0) {
        soma += i;
    }
}

Qual será a saída do código?

int vetor[] = {10, 20, 30, 40, 50};

printf("%d", vetor[2]);

Qual será a saída do código?

int vetor[] = {2, 4, 6, 8};

for (int i = 0; i < 4; i++) {
    vetor[i] = vetor[i] * 2;
}

printf("%d", vetor[3]);

Qual será a saída do código?

int matriz[2][2] = {
    {1, 2},
    {3, 4}
};

printf("%d", matriz[1][0]);

Qual será a saída do código?

void alterar(int *x) {
    *x = 20;
}

int main() {
    int numero = 10;

    alterar(&numero);

    printf("%d", numero);
    return 0;
}

O que o operador & faz em &numero nesse contexto?

int numero = 10;
int *ptr = &numero;

O que o operador * faz quando utilizado para acessar um ponteiro?

int numero = 10;
int *ptr = &numero;

printf("%d", *ptr);

O que a função abaixo retorna quando n recebe o valor 4?

int fatorial(int n) {
    if (n == 0) {
        return 1;
    }

    return n * fatorial(n - 1);
}

printf("%d", fatorial(4));

Qual será a saída do código?

char nome[] = "C";

printf("%c", nome[0]);

Qual será a saída do código?

char texto[] = "ABC";

printf("%d", strlen(texto));

Qual será o valor final de contador?

int contador = 0;

for (int i = 0; i < 3; i++) {
    for (int j = 0; j < 3; j++) {
        contador++;
    }
}

Qual será a saída do código?

int x = 10;
int *p = &x;

*p = 30;

printf("%d", x);

Qual será o resultado da função?

int maior(int a, int b) {
    if (a > b) {
        return a;
    }

    return b;
}

printf("%d", maior(15, 9));

Qual será a saída do código?

int x = 1;

for (int i = 0; i < 5; i++) {
    x *= 2;
}

printf("%d", x);
